questionvariables.text:
/* Generate Pythagorean triples to ensure height and area are perfectly clean integers */
m : rand(4) + 2; 
n : rand(m-1) + 1;
k : rand(4) + 2; 

/* Assign dimensions */
half_base : k * (m^2 - n^2);
height : k * (2*m*n);

/* Randomly swap half_base and height for variety */
if rand(2) = 1 then (
    temp : half_base,
    half_base : height,
    height : temp
);

slant : k * (m^2 + n^2);
base_length : 2 * half_base;

/* Calculations */
area_triangle : (1/2) * base_length * height;
ta : 5 * area_triangle;

/* Specific Mistakes for PRT */
m1 : 5 * (1/2) * base_length * slant;     /* Used slant as height */
m2 : 5 * (1/2) * base_length * half_base; /* Used half-base as height */
m3 : area_triangle;                       /* Forgot to multiply by 5 */
